begin read only;select jsonb_build_object('migration',exists(select 1 from supabase_migrations.schema_migrations where version='20260923120000'),'rls',(select jsonb_build_object('enabled',relrowsecurity,'forced',relforcerowsecurity) from pg_class where oid='public.subcontracts'::regclass),'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='public' and tablename='subcontracts'),'update_columns',(select jsonb_agg(attname order by attname) from pg_attribute where attrelid='public.subcontracts'::regclass and attnum>0 and not attisdropped and has_column_privilege('authenticated','public.subcontracts',attname,'UPDATE')),'permissions',(select jsonb_agg(to_jsonb(p)) from public.role_permissions p where permission_key='subcontract.manage'),'integrity',jsonb_build_object('companies',(select count(*) from public.companies),'settings',(select count(*) from public.company_settings),'missing',(select count(*) from public.companies c left join public.company_settings s on s.company_id=c.id where s.company_id is null),'orphan',(select count(*) from public.company_settings s left join public.companies c on c.id=s.company_id where c.id is null))) preflight;commit;
